import logging
from taf.internal.portforwarding.factory import (RemoteServiceFactory, NetcatRemoteServiceFactory,
                                                 SshForwardableHopFactory, ExtraSshdForwardableHopFactory,
                                                 SshForwardableReverseHopFactory,
                                                 SshForwardableNetcatReverseHopFactory,
                                                 SshForwardingBranchFactory, SshReverseForwardingBranchFactory,
                                                 SshHopFactory, ExtraSshdSshReverseHopFactory,
                                                 KubectlForwardRemoteServiceFactory, NetcatReverseForwardingBranchFactory,
                                                 LxcSshdForwardableHopFactory)


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Portforwarding(object):

    """
    Port forwarding is used for creating a gangplank to destination device.
    """

    @staticmethod
    def create_remote_service(ip, port):
        """
        create a remote service, the service will be mapped to user with port forwarding.
        the service will be used in creating ssh forwarding or reverse branch.
        :param ip: str, remote service ip address.
        :param port: str, remote service port.
        :return RemoteService: remote service object
        """
        return RemoteServiceFactory().create(ip, port)

    @staticmethod
    def create_netcat_remote_service(service_port,
                                     remote_netcat_host,
                                     remote_netcat_port,
                                     nc_listen_template=None,
                                     nc_connect_template=None):
        """
        create a netcat remote service, the service will be mapped to user with port forwarding.
        the service will be used in creating netcat reverse forwarding branch
        :param service_port: str, remote service port
        :param remote_netcat_host: str, the remote host ip address which netcat forward local service to
        :param remote_netcat_port: str, the remote port which netcat forward local service to
        :param nc_listen_template: str, netcat listen command template.
        :param nc_connect_template: str, netcat connect command template.
        :return StartableNetcatRemoteService: startable netcat remoteService object.
        """
        return NetcatRemoteServiceFactory().create(service_port=service_port,
                                                   remote_netcat_host=remote_netcat_host,
                                                   remote_netcat_port=remote_netcat_port,
                                                   nc_listen_template=nc_listen_template,
                                                   nc_connect_template=nc_connect_template)

    @staticmethod
    def create_kubectl_forward_remote_service(namespace,
                                              pod,
                                              port):
        """
        create a kubectl port forward remote service.
        :param namespace: str, kubernetes namespace.
        :param pod: str, kubernetes pod name.
        :param port: int, service port in pod container.
        :return StartableKubectlForwardRemoteService: kubectl port forward remote service.
        """
        return KubectlForwardRemoteServiceFactory().create(namespace=namespace,
                                                           pod=pod,
                                                           port=port)

    @staticmethod
    def create_ssh_hop(host,
                       user=None,
                       password=None,
                       port=22,
                       pkey=None,
                       key_filename=None,
                       timeout=10,
                       initialization_commands=None):
        """
        create a ssh hop.
        :param host: str, hop ip address.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, hop ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshHop: ssh hop.
        """
        return SshHopFactory().create(host=host,
                                      user=user,
                                      password=password,
                                      port=port,
                                      pkey=pkey,
                                      key_filename=key_filename,
                                      timeout=timeout,
                                      initialization_commands=initialization_commands)

    @staticmethod
    def create_ssh_forwardable_hop(host,
                                   user=None,
                                   password=None,
                                   port=22,
                                   pkey=None,
                                   key_filename=None,
                                   timeout=10,
                                   initialization_commands=None):
        """
        create a ssh forwardable hop.
        this hop support direct forwarding.
        :param host: str, hop ip address.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, hop ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableHop: ssh forwardable hop.
        """
        return SshForwardableHopFactory().create(host=host,
                                                 user=user,
                                                 password=password,
                                                 port=port,
                                                 pkey=pkey,
                                                 key_filename=key_filename,
                                                 timeout=timeout,
                                                 initialization_commands=initialization_commands)

    @staticmethod
    def create_ssh_forwardable_reverse_hop(host,
                                           user=None,
                                           password=None,
                                           port=22,
                                           pkey=None,
                                           key_filename=None,
                                           timeout=10,
                                           initialization_commands=None):
        """
        create a ssh forwardable hop.
        this hop support direct forwarding.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableReverseHop: ssh forwardable reverse hop.
        """
        return SshForwardableReverseHopFactory().create(host=host,
                                                        user=user,
                                                        password=password,
                                                        port=port,
                                                        pkey=pkey,
                                                        key_filename=key_filename,
                                                        timeout=timeout,
                                                        initialization_commands=initialization_commands)

    @staticmethod
    def create_extra_sshd_forwardable_hop(new_sshd_port,
                                          host,
                                          user=None,
                                          password=None,
                                          port=22,
                                          sudo_prefix="",
                                          pkey=None,
                                          key_filename=None,
                                          timeout=10,
                                          initialization_commands=None):
        """
        create a hop, need startup new sshd service for getting ssh forwarding function.
        :param new_sshd_port: str, new sshd service binding port.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return ExtraSshdForwardableHop: extra sshd forwardable hop.
        """
        return ExtraSshdForwardableHopFactory().create(host=host,
                                                       user=user,
                                                       password=password,
                                                       port=port,
                                                       new_sshd_port=new_sshd_port,
                                                       sudo_prefix=sudo_prefix,
                                                       pkey=pkey,
                                                       key_filename=key_filename,
                                                       timeout=timeout,
                                                       initialization_commands=initialization_commands)

    @staticmethod
    def create_lxc_sshd_forwardable_hop(host_hop,
                                        containerid,
                                        host,
                                        user=None,
                                        password=None,
                                        port=22,
                                        sudo_prefix="",
                                        timeout=10,
                                        initialization_commands=None):
        """
        create LxcSshdForwardableHop object, under steps will be processed.
        step1: using "lxc-attach"command enter into container
        step2: startup a sshd service with input confguration.
        step3: create ssh connection to container.
        :param host_hop: Hop, The host hop which container belong to.
        :param containerid: str, container id.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return LxcSshdForwardableHop: lxc sshd forwardable hop.
        """
        return LxcSshdForwardableHopFactory().create(host_hop=host_hop,
                                                     containerid=containerid,
                                                     host=host,
                                                     user=user,
                                                     password=password,
                                                     port=port,
                                                     sudo_prefix=sudo_prefix,
                                                     timeout=timeout,
                                                     initialization_commands=initialization_commands)

    @staticmethod
    def create_extra_sshd_ssh_reverse_hop(host,
                                          user=None,
                                          password=None,
                                          port=22,
                                          new_sshd_port=None,
                                          sudo_prefix="",
                                          pkey=None,
                                          key_filename=None,
                                          timeout=10,
                                          initialization_commands=None):
        """
        create a hop, need startup new sshd service and support reverse forwarding.
        :param host: str, ip address of hop.
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param new_sshd_port: str, new sshd service binding port.
        :param sudo_prefix: str, if login username is not root, should specify sudo_prefix="sudo ".
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return ExtraSshdSshReverseHop: extra sshd reverse hop.
        """
        return ExtraSshdSshReverseHopFactory().create(host=host,
                                                      user=user,
                                                      password=password,
                                                      port=port,
                                                      new_sshd_port=new_sshd_port,
                                                      sudo_prefix=sudo_prefix,
                                                      pkey=pkey,
                                                      key_filename=key_filename,
                                                      timeout=timeout,
                                                      initialization_commands=initialization_commands)

    @staticmethod
    def create_ssh_forwardable_netcat_hop(host,
                                          local_netcat_port,
                                          remote_netcat_host,
                                          remote_netcat_port,
                                          user=None,
                                          password=None,
                                          port=22,
                                          nc_listen_template=None,
                                          nc_connect_template=None,
                                          pkey=None,
                                          key_filename=None,
                                          timeout=10,
                                          initialization_commands=None):
        """
        create a forwardable netact hop, support starting and stopping netcat forwarding.
        :param host: str, ip address of hop.
        :param local_netcat_port: int, netcat local listening port.
        :param remote_netcat_host: str, the remote host ip address which netcat forward local service to
        :param remote_netcat_port: str, the remote port which netcat forward local service to
        :param user: str, ssh login username.
        :param password: str, ssh login password.
        :param port: int, ssh port.
        :param nc_listen_template: str, netcat listen command template.
        :param nc_connect_template: str, netcat connect command template.
        :param pkey: PKey, an optional private key to use for authentication.
        :param key_filename: str, the filename, or list of filenames, of optional private key(s)
            and/or certs to try for authentication.
        :param timeout: float, timeout (in seconds) for ssh connecting, default 10s.
        :param initialization_commands: list, specified the commands which will be executed after hop setup,
            default empty.
        :return SshForwardableNetcatReverseHop: ssh forwardable netcat reverse Hop.
        """
        return SshForwardableNetcatReverseHopFactory().create(host=host,
                                                              local_netcat_port=local_netcat_port,
                                                              remote_netcat_host=remote_netcat_host,
                                                              remote_netcat_port=remote_netcat_port,
                                                              user=user,
                                                              password=password,
                                                              port=port,
                                                              nc_listen_template=nc_listen_template,
                                                              nc_connect_template=nc_connect_template,
                                                              pkey=pkey,
                                                              key_filename=key_filename,
                                                              timeout=timeout,
                                                              initialization_commands=initialization_commands)

    @staticmethod
    def create_ssh_forwarding_branch(hops,
                                     remote_service,
                                     forwarding_port=0):
        """
        create a forward ssh branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param remote_service: RemoteService, remote service.
        :param forwarding_port: Optional[int], forwarding port mapping to remote service,
            which is specified as test vm server port. default is 0, will select free port automatically.
        :return Branch: ssh forwarding branch.
        """
        return SshForwardingBranchFactory().create(hops=hops,
                                                   forwarding_port=forwarding_port,
                                                   remote_service=remote_service)

    @staticmethod
    def create_ssh_reverse_branch(hops,
                                  remote_service,
                                  forwarding_port=0):
        """
        create a reverse ssh branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param remote_service: RemoteService, remote service.
        :param forwarding_port: Optional[int], forwarding port mapping to remote service,
            which is specified as last hop ssh listen server port. default is 0, will select free port automatically.
        :return Branch: ssh reverse forwarding branch.
        """
        return SshReverseForwardingBranchFactory().create(hops=hops,
                                                          forwarding_port=forwarding_port,
                                                          remote_service=remote_service)

    @staticmethod
    def create_netcat_reverse_branch(hops,
                                     startable_remote_service):
        """
        create a reverse netcat branch.
        build dependency relationships between hops.
        config hops based dependency information.
        :param hops: list, hop object list.
        :param startable_remote_service: StartableNetcatRemoteService, startable remote service.
        :return Branch: netcat reverse branch.
        """
        return NetcatReverseForwardingBranchFactory().create(hops, startable_remote_service)
